SELECT v.data, s.nome AS struttura, s.paese
FROM visite v JOIN strutture s ON s.id = v.struttura_id
WHERE v.tipo = 'ricovero' ORDER BY v.data DESC LIMIT 50;

SELECT s.paese, count(*) AS visite
FROM visite v JOIN strutture s ON s.id = v.struttura_id
GROUP BY s.paese ORDER BY visite DESC;

SELECT s.nome, s.tipo, count(p.id) AS pazienti
FROM strutture s LEFT JOIN pazienti p ON p.struttura_registrazione_id = s.id
WHERE s.attiva = 1 GROUP BY s.id, s.nome, s.tipo ORDER BY pazienti DESC;

SELECT codice, data_nascita,
       CAST((julianday('2026-09-01') - julianday(data_nascita)) / 365.25 AS INTEGER) AS eta
FROM pazienti ORDER BY eta DESC LIMIT 30;

SELECT esito, count(*) AS n,
       round(100.0 * count(*) / (SELECT count(*) FROM visite), 2) AS percentuale
FROM visite GROUP BY esito ORDER BY n DESC;

SELECT p.codice, p.regione, count(v.id) AS visite
FROM pazienti p JOIN visite v ON v.paziente_id = p.id
GROUP BY p.id, p.codice, p.regione ORDER BY visite DESC, p.codice LIMIT 15;

SELECT pr.nome, pr.paese, count(si.id) AS siti, sum(si.popolazione_stimata) AS popolazione
FROM progetti pr JOIN siti si ON si.progetto_id = pr.id
GROUP BY pr.id, pr.nome, pr.paese ORDER BY popolazione DESC;

SELECT i.codice, i.nome, round(avg(m.valore), 2) AS valore_medio, count(m.valore) AS misurazioni_valide
FROM indicatori i JOIN misurazioni m ON m.indicatore_id = i.id
GROUP BY i.id, i.codice, i.nome ORDER BY i.codice;

SELECT s.nome, s.tipo, s.paese FROM strutture s
LEFT JOIN visite v ON v.struttura_id = s.id
WHERE v.id IS NULL ORDER BY s.nome;

SELECT articolo, sum(quantita) AS quantita, sum(beneficiari) AS beneficiari,
       round(sum(quantita * costo_unitario_eur), 2) AS costo_eur
FROM distribuzioni GROUP BY articolo ORDER BY costo_eur DESC;

SELECT analita, count(*) AS esami,
       round(100.0 * sum(fuori_range) / count(*), 2) AS pct_fuori_range
FROM esami_lab GROUP BY analita HAVING count(*) >= 50 ORDER BY pct_fuori_range DESC;

SELECT d.id, s.nome AS sito, d.articolo, d.quantita, d.beneficiari
FROM distribuzioni d JOIN siti s ON s.id = d.sito_id
WHERE d.beneficiari > d.quantita ORDER BY (d.beneficiari - d.quantita) DESC;

SELECT s.nome, s.paese,
       (SELECT max(v.data) FROM visite v WHERE v.struttura_id = s.id) AS ultima_visita
FROM strutture s WHERE s.attiva = 1 ORDER BY ultima_visita DESC;

SELECT v.id, v.data, v.strumento, v.responsabile
FROM valutazioni v LEFT JOIN misurazioni m ON m.valutazione_id = v.id
WHERE v.completata = 1 AND m.id IS NULL ORDER BY v.data DESC;

SELECT pr.nome, pr.paese, pr.stato FROM progetti pr
WHERE EXISTS (SELECT 1 FROM siti s WHERE s.progetto_id = pr.id AND s.accessibile = 0)
ORDER BY pr.nome;

SELECT p.codice, p.regione, p.data_registrazione FROM pazienti p
WHERE NOT EXISTS (SELECT 1 FROM visite v WHERE v.paziente_id = p.id)
ORDER BY p.data_registrazione DESC LIMIT 50;

SELECT data_nascita, sesso, regione, count(*) AS n, group_concat(codice) AS codici
FROM pazienti GROUP BY data_nascita, sesso, regione HAVING count(*) > 1
ORDER BY n DESC LIMIT 40;

SELECT nome, donatore, budget_eur,
       round(PERCENT_RANK() OVER (ORDER BY budget_eur), 3) AS percentile
FROM progetti ORDER BY budget_eur DESC;

EXPLAIN QUERY PLAN
SELECT s.nome, count(v.id) AS n FROM strutture s
LEFT JOIN visite v ON v.struttura_id = s.id GROUP BY s.id, s.nome;

WITH c AS (SELECT farmaco, count(*) AS n FROM prescrizioni GROUP BY farmaco)
SELECT farmaco, n, RANK() OVER (ORDER BY n DESC) AS rango,
       DENSE_RANK() OVER (ORDER BY n DESC) AS rango_denso FROM c ORDER BY n DESC;

SELECT pr.id, pr.farmaco, v.data AS inizio,
       date(v.data, '+' || pr.giorni || ' days') AS fine
FROM prescrizioni pr JOIN visite v ON v.id = pr.visita_id ORDER BY pr.id LIMIT 40;

SELECT v.id, json_group_array(d.codice_icd10) AS diagnosi
FROM visite v JOIN diagnosi d ON d.visita_id = v.id
GROUP BY v.id ORDER BY v.id LIMIT 30;
